WITH f_all AS (SELECT user1 AS a, user2 AS b FROM friends UNION SELECT user2, user1 FROM friends) SELECT DISTINCT u1.name AS name1, u2.name AS name2, u3.name AS name3 FROM f_all f1 JOIN f_all f2 ON f1.b = f2.a AND f1.a != f2.b JOIN f_all f3 ON f2.b = f3.a AND f3.b = f1.a JOIN users u1 ON u1.id = f1.a JOIN users u2 ON u2.id = f1.b JOIN users u3 ON u3.id = f2.b WHERE f1.a < f1.b AND f1.b < f2.b ORDER BY name1;
